Chương 6. KIỂU DỮ LIỆU CẤU TRÚC VÀ TẬP TIN

Số tiết: 04 tiết lý thuyết + 04 tiết thực hành (Tuần 14 – 15)

 MỤC TIÊU CỦA CHƯƠNG (CLO3, CLO4):
 1) Định nghĩa kiểu struct, khai báo và thao tác trên biến struct và mảng struct.
 2) Xây dựng chương trình quản lý danh sách đối tượng bằng mảng struct.
 3) Đọc và ghi dữ liệu vào tệp văn bản và tệp nhị phân.
 4) Thiết kế chương trình quản lý dữ liệu kết hợp struct, hàm và tệp; rèn kỹ năng gỡ
 lỗi.

6.1. Kiểu cấu trúc

6.1.1. Khái niệm và lý do sử dụng struct

        Khi quản lý thông tin một sinh viên, cần nhiều biến liên quan: mã số, họ tên, năm
sinh, các điểm số... Nếu quản lý 100 sinh viên, sẽ cần rất nhiều biến riêng lẻ. Kiểu struct
cho phép nhóm các trường dữ liệu liên quan thành MỘT kiểu dữ liệu mới, giúp tổ chức
chương trình gọn gàng và tự nhiên hơn.
        Khác với mảng (nơi mọi phần tử phải CÙNG một kiểu dữ liệu), struct cho phép
nhóm các thành phần có KIỂU DỮ LIỆU KHÁC NHAU vào trong một biến duy nhất.
Đây chính là điểm khác biệt căn bản và cũng là lý do struct phù hợp để mô tả các đối
tượng thực tế, vốn thường có nhiều thuộc tính khác kiểu (ví dụ: mã sinh viên là chuỗi,
năm sinh là số nguyên, điểm số là số thực).

6.1.2. Định nghĩa và khai báo struct

        Việc sử dụng struct gồm hai giai đoạn: trước tiên ĐỊNH NGHĨA kiểu struct mới
(mô tả các thành phần sẽ có), sau đó mới KHAI BÁO các biến thuộc kiểu struct đó.

Cú pháp chung:
 // Cách 1: định nghĩa struct dùng tag
 struct tên_struct {
         kiểu_dữ_liệu_1 tên_thành_phần_1;

                                           - 58 -
      kiểu_dữ_liệu_2 tên_thành_phần_2;
      ...
 };
 struct tên_struct tên_biến;// Khai báo biến (phải có từ khóa struct)

 // Cách 2: dùng typedef để đặt tên ngắn gọn hơn
 typedef struct {
      kiểu_dữ_liệu_1 tên_thành_phần_1;
      kiểu_dữ_liệu_2 tên_thành_phần_2;
      ...
 } TênKiểuMới;
 TênKiểuMới tên_biến;// Khai báo biến (KHÔNG cần từ khóa struct)

Trong đó:
   – tên_thành_phần (member/field): các trường dữ liệu của struct, có thể thuộc nhiều
       kiểu khác nhau.
   – Với cách 1, mỗi lần khai báo biến phải viết đầy đủ "struct tên_struct"; với cách 2
       (typedef), chỉ cần viết TênKiểuMới.

Ví dụ cụ thể sau vận dụng cả hai cách định nghĩa struct nói trên cho đối tượng sinh viên:
 /* Định nghĩa struct dùng tag */
 struct SinhVien {
      char maSV[12];
      char hoTen[60];
      int namSinh;
      float diemToan, diemLy, diemHoa;
 };
 struct SinhVien sv1;
 struct SinhVien ds[100];

 /* typedef - đặt tên ngắn gọn, không cần viết lại 'struct' mỗi lần
 */
 typedef struct {
      char maSV[12];
      char hoTen[60];
      float diemToan, diemLy, diemHoa, diemTB;
 } SinhVien;

 SinhVien sv2;

                                         - 59 -
 SinhVien kho[200];

6.1.3. Truy xuất và thao tác với struct

      Sau khi đã khai báo biến struct, ta cần một cú pháp riêng để truy cập vào TỪNG
thành phần bên trong biến đó. C cung cấp hai toán tử truy xuất, tùy theo biến struct là
biến thường hay con trỏ trỏ đến struct.

Cú pháp chung:
 tên_biến.tên_thành_phần                              // Truy xuất qua biến struct
 thường (dấu chấm)
 tên_con_trỏ->tên_thành_phần                        // Truy xuất qua con trỏ struct
 (dấu mũi tên)
 (*tên_con_trỏ).tên_thành_phần                  // Tương đương với cách trên, ít
 dùng hơn

Trong đó:
     – Dấu . (chấm): dùng khi tên_biến là một biến struct thông thường (không phải con
        trỏ).
     – Dấu -> (mũi tên): dùng khi tên_con_trỏ là một con trỏ trỏ đến struct; viết gọn
        hơn (*p).thành_phần.

      Ví dụ cụ thể sau vận dụng cả hai toán tử truy xuất struct, kết hợp với việc truyền
con trỏ struct vào hàm để tăng hiệu quả:
 typedef struct {
        char maSV[12]; char hoTen[60];
        float diemToan, diemLy, diemHoa, diemTB;
 } SinhVien;

 float tinhDiemTB(SinhVien sv) {
        return (sv.diemToan + sv.diemLy + sv.diemHoa) / 3.0f;
 }

 /* Truyền con trỏ để tránh sao chép toàn bộ struct (hiệu quả hơn)
 */
 void nhapSV(SinhVien *sv) {
        printf("Ma SV: "); scanf("%11s", sv->maSV);
        printf("D.Toan: "); scanf("%f", &sv->diemToan);

                                           - 60 -
       sv->diemTB = tinhDiemTB(*sv);
 }

 int main() {
       SinhVien sv1 = {"SV001", "Nguyen Van An", 8.5f, 7.0f, 9.0f, 0};
     sv1.diemTB = tinhDiemTB(sv1);                     /* Truy xuất qua biến:
 sv.truong */

       SinhVien *p = &sv1;
     printf("%s\n", p->hoTen);                      /* Truy xuất qua con trỏ:
 p->truong */
       return 0;
 }

6.1.4. Mảng struct và ứng dụng quản lý danh sách
 #define MAX_SV 100

 void sapXepTheoTB(SinhVien ds[], int n) {
       for (int i = 0; i < n-1; i++)
            for (int j = 0; j < n-1-i; j++)
                 if (ds[j].diemTB < ds[j+1].diemTB) {
                       SinhVien t = ds[j]; ds[j] = ds[j+1]; ds[j+1] = t;
                 }
 }

 int timTheoMa(SinhVien ds[], int n, const char *ma) {
       for (int i = 0; i < n; i++)
            if (strcmp(ds[i].maSV, ma) == 0) return i;
       return -1;
 }

6.2. Kiểu tập tin

6.2.1. Sự cần thiết của tệp (file)

     Dữ liệu trong bộ nhớ RAM bị mất khi chương trình kết thúc. Tệp (file) cho phép
lưu dữ liệu một cách bền vững (persistent) trên đĩa, có thể đọc lại ở những lần chạy
chương trình sau.

                                       - 61 -
                        Bảng 6.1. So sánh tệp văn bản và tệp nhị phân

      Đặc điểm                  Tệp văn bản (Text)             Tệp nhị phân (Binary)

 Định dạng lưu          Chuỗi ký tự ASCII, mỗi dòng kết Dữ liệu nhị phân theo định dạng
                        thúc bằng \n                      bộ nhớ

 Mở     được      bằng Có, đọc được trực tiếp             Không, hiển thị ký tự không đọc
 Notepad?                                                 được

 Tốc độ đọc/ghi         Chậm hơn (cần định dạng/phân Nhanh hơn (sao chép trực tiếp từ
                        tích)                             bộ nhớ)

 Phù hợp dùng cho       Tệp cấu hình, log, dữ liệu CSV    Lưu trữ dữ liệu lớn, chính xác cao

6.2.2. Làm việc với tệp văn bản

      Để làm việc với một tệp bất kỳ trong C, luôn cần theo trình tự ba bước: mở tệp
(fopen), thao tác đọc/ghi trên tệp, và đóng tệp (fclose) khi hoàn tất.

Cú pháp chung:
 FILE *con_trỏ_file = fopen("tên_tệp", "chế_độ");
 if (con_trỏ_file == NULL) { /* xử lý lỗi mở tệp thất bại */ }

 fprintf(con_trỏ_file, "chuỗi_định_dạng", đối_số...);                         // Ghi có
 định dạng
 fscanf(con_trỏ_file, "chuỗi_định_dạng", &biến...);                      // Đọc có định
 dạng
 fgets(buf, kích_thước, con_trỏ_file);                                       // Đọc một
 dòng văn bản

 fclose(con_trỏ_file);             // Luôn đóng tệp sau khi dùng xong

Trong đó:
   – FILE *: kiểu con trỏ đặc biệt đại diện cho một tệp đang mở, do thư viện stdio.h
       định nghĩa.
   – chế_độ: quy định cách mở tệp — "r" (đọc), "w" (ghi, tạo mới/ghi đè), "a" (ghi
       nối thêm vào cuối tệp).
   – fopen() trả về NULL nếu mở tệp thất bại (ví dụ tệp không tồn tại khi mở ở chế
       độ đọc) — luôn phải kiểm tra.

                                            - 62 -
Ví dụ cụ thể sau vận dụng cú pháp tổng quát nói trên để ghi, đọc và ghi nối thêm dữ liệu
vào một tệp văn bản:
 FILE *fw = fopen("diem.txt", "w");                   /* Mở để ghi (tạo mới/ghi
 đè) */
 if (fw == NULL) { perror("Loi mo file"); return 1; }
 fprintf(fw, "SV001,Nguyen Van An,8.5\n");
 fclose(fw);                                          /* LUÔN đóng file sau khi
 dùng */

 FILE *fr = fopen("diem.txt", "r");                   /* Mở để đọc */
 char dong[200];
 while (fgets(dong, sizeof(dong), fr) != NULL) printf("%s", dong);
 fclose(fr);

 FILE *fa = fopen("diem.txt", "a");                  /* Mở để ghi thêm (append)
 */
 fprintf(fa, "SV002,Tran Thi Bich,7.8\n");
 fclose(fa);

6.2.3. Làm việc với tệp nhị phân

     Khác với fprintf/fscanf làm việc với dữ liệu dạng văn bản, đọc/ghi tệp nhị phân
dùng cặp hàm fwrite/fread để sao chép trực tiếp vùng nhớ của biến (hoặc mảng) vào/ra
tệp, mở tệp ở chế độ có thêm ký tự "b" (binary).

Cú pháp chung:
 FILE *con_trỏ_file = fopen("tên_tệp", "wb");                // wb: ghi nhị phân,
 rb: đọc nhị phân

 fwrite(địa_chỉ_dữ_liệu,              kích_thước_1_phần_tử,             số_phần_tử,
 con_trỏ_file);
 fread(địa_chỉ_dữ_liệu,              kích_thước_1_phần_tử,              số_phần_tử,
 con_trỏ_file);

Trong đó:
   – địa_chỉ_dữ_liệu: địa chỉ của biến/mảng cần ghi ra tệp hoặc đọc dữ liệu vào.
   – kích_thước_1_phần_tử: thường dùng sizeof(kiểu_dữ_liệu) để tự động tính đúng
      số byte.

                                         - 63 -
     – số_phần_tử: số lượng phần tử cần ghi/đọc (1 nếu là một biến đơn, n nếu là mảng
        n phần tử).

      Ví dụ cụ thể sau vận dụng cú pháp fwrite/fread để ghi và đọc lại một mảng struct
SinhVien dưới dạng tệp nhị phân:
 int ghiFileBinary(const char *tenFile, SinhVien ds[], int n) {
        FILE *f = fopen(tenFile, "wb");
        if (!f) return 0;
        fwrite(&n, sizeof(int), 1, f);
        fwrite(ds, sizeof(SinhVien), n, f);
        fclose(f);
        return 1;
 }

 int docFileBinary(const char *tenFile, SinhVien ds[], int *n) {
        FILE *f = fopen(tenFile, "rb");
        if (!f) return 0;
        fread(n, sizeof(int), 1, f);
        fread(ds, sizeof(SinhVien), *n, f);
        fclose(f);
        return 1;
 }

6.2.4. Một số hàm tệp quan trọng

                      Bảng 6.2. Các hàm thao tác tệp thường dùng trong C

                Hàm                    Trả về                      Chức năng

fopen(path, mode)               FILE* hoặc NULL       Mở file. Modes: r, w, a, rb, wb, ab

fclose(fp)                      0 hoặc EOF            Đóng file, giải phóng tài nguyên

fprintf / fscanf                Số ký tự / số biến    Ghi / đọc dữ liệu có định dạng

fgets / fputs                   buf / số ký tự        Đọc / ghi một dòng văn bản

fread / fwrite                  Số phần tử            Đọc / ghi dữ liệu nhị phân

feof(fp)                        Khác 0 nếu hết file   Kiểm tra đã đến cuối tệp

remove(path)                    0 nếu thành công      Xóa tệp khỏi đĩa

